package androidx.activity;
public class ComponentActivity extends android.content.Context { private android.view.Window window=new android.view.Window(); public void onCreate(android.os.Bundle b){} public void onStart(){} public void onStop(){} public void onDestroy(){} public android.view.Window getWindow(){return window;} public void setContentView(android.view.View v){window.root=v;} public android.app.Application getApplication(){return new android.app.Application();} public OnBackPressedDispatcher getOnBackPressedDispatcher(){return new OnBackPressedDispatcher();} public boolean isFinishing(){return false;} public android.content.Intent lastIntent; public void startActivity(android.content.Intent i){lastIntent=i;} public android.view.View getCurrentFocus(){return null;} public boolean moveTaskToBack(boolean b){return true;} }
